CREATE TABLE IF NOT EXISTS gst_statutory_closes(close_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, organization_id TEXT NOT NULL, entity_id TEXT, period_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', compliance_status TEXT NOT NULL DEFAULT 'PENDING', settlement_status TEXT NOT NULL DEFAULT 'PENDING', acknowledgement_status TEXT NOT NULL DEFAULT 'PENDING', exception_count INTEGER NOT NULL DEFAULT 0, locked_by TEXT, locked_at TIMESTAMP, reopened_by TEXT, reopened_at TIMESTAMP, remarks TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id));
CREATE TABLE IF NOT EXISTS gst_statutory_close_audit(audit_id TEXT PRIMARY KEY, close_id TEXT NOT NULL, action TEXT NOT NULL, from_status TEXT, to_status TEXT, reason TEXT, actor_id TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
